import{_ as e,a0 as i,w as u,s as f,ao as s,I as n,x as o,a1 as r,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"從監獄到 Python | LCTT x X-CMD","titleTemplate":false,"description":"從監獄到 Python | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"從監獄到 Python | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"從監獄到 Python | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200112 What I learned going from prison to Python","title":"從監獄到 Python","tag":"202002","desc":""},"relativePath":"202002/20200112 What I learned going from prison to Python.md","filePath":"[post].md"}'),d={name:"202002/20200112 What I learned going from prison to Python.md"};function a(m,t,y,P,g,T){const l=i("Link");return u(),f("div",null,[t[47]||(t[47]=s('<h1 id="從監獄到-python" tabindex="-1">從監獄到 Python <a class="header-anchor" href="#從監獄到-python" aria-label="Permalink to “從監獄到 Python”">​</a></h1><blockquote><p>入獄後，開源編程是如何提供機會的。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/books_programming_languages.jpg?itok=KJcdnXM2" alt="書架上的編程書籍" title="Programming books on a shelf"></p><p>不到一年前，我還在聖昆廷州立監獄服刑，我是無期徒刑。</p><p>我高三的時候，我搶劫了一個人並向他開了槍。現在，我經過一段時間才意識到並承認自己做錯了，這是在經歷了陪審團審判並看到我的行為帶來的惡果後，我知道需要改變自己，我也確實做到了。儘管我對我的行為表示懊悔，但我畢竟開槍打了一個人，並差點殺了他。做這樣的事是有後果的，這是理所當然的。所以在我 18 歲的時候，我被判了終身監禁。</p><p>監獄是一個非常可怕的地方；我是不推薦你去的。但是我必須去，所以我去了。我不告訴你具體的細節，但你可以放心，這是一個沒有太多動機去改變的地方，許多人在這裏養成的壞習慣比他們過去在別處養成的更多。</p><p>我是幸運兒之一。當我在服刑的時候，發生了一些不同尋常的事情。我開始想像自己出獄後的的未來，雖然在這之前，我還是已經在那裏度過了我整個成年生活。</p><p>現在你想想：我是黑人，只受過高中教育。我沒有工作經歷，如果我離開監獄，在被釋放前，我還是一個被定罪的重罪犯。當每個僱主看到我的簡歷，都不會有“我需要僱用這個人”想法，我認為是正常的。</p><p>我不知道我的選擇是什麼，但我已經下定決心了。我需要做些活下去的事情，並且這和我入獄前的生活一點也不像。</p><h3 id="python-之路" tabindex="-1">Python 之路 <a class="header-anchor" href="#python-之路" aria-label="Permalink to “Python 之路”">​</a></h3>',10)),n("p",null,[t[1]||(t[1]=o("最終，我被關在了聖昆廷州立監獄，我不知道我為何幸運地被關在那裏。聖昆廷提供了幾個自助和教育編程項目。這些",-1)),r(l,{href:"https://www.dailycal.org/2019/02/27/san-quentin-rehabilitation-programs-offer-inmates-education-a-voice/"},{default:p(()=>[...t[0]||(t[0]=[o("改造機會",-1)])]),_:1}),t[2]||(t[2]=o("幫助囚犯使他們擁有在獲釋後避免再次犯罪的技能。",-1))]),n("p",null,[t[5]||(t[5]=o("作為其中一個編程項目的一部分，2017 年我通過聖昆廷媒體項目認識了",-1)),r(l,{href:"https://twitter.com/jessicamckellar?lang=en"},{default:p(()=>[...t[3]||(t[3]=[o("傑西卡·麥凱拉",-1)])]),_:1}),t[6]||(t[6]=o("。傑西卡是編程語言 ",-1)),r(l,{href:"https://www.python.org/"},{default:p(()=>[...t[4]||(t[4]=[o("Python",-1)])]),_:1}),t[7]||(t[7]=o(" 的愛好者，她開始向我推薦 Python 有多棒，以及它是剛起步的人學習的完美語言。這就是故事變得比小説更精彩的地方。",-1))]),n("blockquote",null,[n("p",null,[t[11]||(t[11]=o("感謝 ",-1)),r(l,{href:"https://twitter.com/northbaypython?ref_src=twsrc%5Etfw"},{default:p(()=>[...t[8]||(t[8]=[o("@northbaypython",-1)])]),_:1}),t[12]||(t[12]=o(" 讓 ",-1)),r(l,{href:"https://twitter.com/ShaStepter?ref_src=twsrc%5Etfw"},{default:p(()=>[...t[9]||(t[9]=[o("@ShaStepter",-1)])]),_:1}),t[13]||(t[13]=o(" 和我重複 ",-1)),r(l,{href:"https://twitter.com/pycon?ref_src=twsrc%5Etfw"},{default:p(()=>[...t[10]||(t[10]=[o("@pycon",-1)])]),_:1}),t[14]||(t[14]=o(" 的主題演講，讓他們被錄製下來。我很榮幸與大家分享：",-1))]),n("p",null,[t[16]||(t[16]=o("從監獄到 Pythone: ",-1)),r(l,{href:"https://t.co/rcumoAgZHm"},{default:p(()=>[...t[15]||(t[15]=[o("https://t.co/rcumoAgZHm",-1)])]),_:1})]),n("p",null,[t[18]||(t[18]=o("大規模裁員:如果我們不僱傭被判重罪的人，誰會呢？ ",-1)),r(l,{href:"https://t.co/fENDUFdxfX"},{default:p(()=>[...t[17]||(t[17]=[o("https://t.co/fENDUFdxfX",-1)])]),_:1})]),n("p",null,[r(l,{href:"https://t.co/Kpjo8d3ul6"},{default:p(()=>[...t[19]||(t[19]=[o("pic.Twitter.com/kpjo8d3ul6",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=o("—傑西卡·麥凱拉（@jessicamckellar）",-1)),r(l,{href:"https://twitter.com/jessicamckellar/status/1191601209917837312?ref_src=twsrc%5Etfw"},{default:p(()=>[...t[20]||(t[20]=[o("2019 年 11 月 5 日",-1)])]),_:1})])]),n("p",null,[t[23]||(t[23]=o("傑西卡向我介紹了一些 Python 視頻教程，這些教程是她為一家名叫 ",-1)),r(l,{href:"http://shop.oreilly.com/product/110000448.do"},{default:p(()=>[...t[22]||(t[22]=[o("O’Reilly Media",-1)])]),_:1}),t[24]||(t[24]=o(" 的公司做的，課程是在線的，如果我能接觸到它們，那該有多好呀。不幸的是，在監獄裏上網是不可能的。但是，我遇到了一個叫 Tim O’Reilly 的人，他最近剛來到聖昆廷。在他訪問之後，Tim 從他的公司 O’Reilly Media 公司向監獄的編程班捐贈了大量內容。最終，我拿到了一款平板電腦，上面有傑西卡的 Python 教程，並學會了如何使用這些 Python 教程進行編碼。",-1))]),t[48]||(t[48]=s('<p>真是難以置信。背景和生活與我完全不同的陌生人把這些聯繫在一起，讓我學會了編碼。</p><h3 id="對-python-社區的熱愛" tabindex="-1">對 Python 社區的熱愛 <a class="header-anchor" href="#對-python-社區的熱愛" aria-label="Permalink to “對 Python 社區的熱愛”">​</a></h3><p>在這之後，我開始經常和傑西卡見面，她開始告訴我關於開源社區的情況。我瞭解到，從根本上説，開源社區就是關於夥伴關係和協作的社區。之所以如此有效，是因為沒有人被排除在外。</p><p>對我來説，一個努力尋找自己定位的人，我所看到的是一種非常基本的愛——通過合作和接受的愛，通過接觸的愛，通過包容的愛。我渴望成為其中的一部分。所以我繼續學習 Python，不幸的是，我無法獲得更多的教程，但是我能夠從開源社區收集的大量書面知識中獲益。我讀一切提到 Python 的東西，從平裝本到晦澀難懂的雜誌文章，我使用平板電腦來解決我讀到的 Python 問題。</p><p>我對 Python 和編程的熱情不是我的許多同齡人所共有的。除了監獄編程課上的極少數人之外，我認識的其他人都沒有提到過編程；一般囚犯都不知道。我認為這是因為有過監禁經歷的人無法接觸編程，尤其是如果你是有色人種。</p><h3 id="監獄外的-python-生活" tabindex="-1">監獄外的 Python 生活 <a class="header-anchor" href="#監獄外的-python-生活" aria-label="Permalink to “監獄外的 Python 生活”">​</a></h3><p>然而，在 2018 年 8 月 17 日，我得到了生命中的驚喜。時任州長的傑裏·布朗將我 27 年的刑期減刑，在服刑將近 19 年後，我被釋放出獄了。</p><p>但現實情況是，這也是為什麼我認為編程和開源社區如此有價值。我是一名 37 歲的黑人罪犯，沒有工作經歷，剛剛在監獄服刑 18 年。我有犯罪史，並且現存偏見導致沒有多少職業適合我。但是編程是少數例外之一。</p><p>現在，監禁後重返社會的人們迫切需要包容，但當談及工作場所的多樣性以及對多樣性的需求時，你真的聽不到這個羣體被提及或包容。</p>',9)),n("blockquote",null,[t[28]||(t[28]=n("p",null,"還有什麼:",-1)),t[29]||(t[29]=n("p",null,"1、背景調查：詢問他們在你的公司是如何使用的。",-1)),t[30]||(t[30]=n("p",null,"2、初級角色：刪除虛假的、不必要的先決條件，這些條件將排除有記錄的合格人員。",-1)),t[31]||(t[31]=n("p",null,"3、積極拓展：與當地再就業項目合作，創建招聘渠道。",-1)),n("p",null,[r(l,{href:"https://t.co/WnzdEUTuxr"},{default:p(()=>[...t[25]||(t[25]=[o("pic.twitter.com/WnzdEUTuxr",-1)])]),_:1})]),n("p",null,[t[27]||(t[27]=o("—傑西卡·麥凱拉（@jessicamckellar）",-1)),r(l,{href:"https://twitter.com/jessicamckellar/status/1127640222504636416?ref_src=twsrc%5Etfw"},{default:p(()=>[...t[26]||(t[26]=[o("2019 年 5 月 12 日",-1)])]),_:1})])]),t[49]||(t[49]=n("p",null,"因此，我想謙卑地挑戰開源社區的所有程序員和成員，讓他們圍繞包容和多樣性展開思考。今天，我自豪地站在你們面前，代表一個大多數人都沒有想到的羣體——以前被監禁的人。但是我們存在，我們渴望證明我們的價值，最重要的是，我們期待被接受。當我們重返社會時，許多挑戰等待着我們，我請求你們允許我們有機會展示我們的價值。歡迎我們，接受我們，最重要的是，包容我們。",-1)),t[50]||(t[50]=n("hr",null,null,-1)),n("p",null,[t[33]||(t[33]=o("via: ",-1)),r(l,{href:"https://opensource.com/article/20/1/prison-to-python"},{default:p(()=>[...t[32]||(t[32]=[o("https://opensource.com/article/20/1/prison-to-python",-1)])]),_:1})]),n("p",null,[t[38]||(t[38]=o("作者：",-1)),r(l,{href:"https://opensource.com/users/shastepter"},{default:p(()=>[...t[34]||(t[34]=[o('Shadeed "Sha" Wallace-Stepter',-1)])]),_:1}),t[39]||(t[39]=o(" 選題：",-1)),r(l,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[35]||(t[35]=[o("lujun9972",-1)])]),_:1}),t[40]||(t[40]=o(" 譯者：",-1)),r(l,{href:"https://github.com/heguangzhi"},{default:p(()=>[...t[36]||(t[36]=[o("heguangzhi",-1)])]),_:1}),t[41]||(t[41]=o(" 校對：",-1)),r(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[37]||(t[37]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[44]||(t[44]=o("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[42]||(t[42]=[o("LCTT",-1)])]),_:1}),t[45]||(t[45]=o(" 原創編譯，",-1)),r(l,{href:"https://linux.cn/"},{default:p(()=>[...t[43]||(t[43]=[o("Linux中國",-1)])]),_:1}),t[46]||(t[46]=o(" 榮譽推出",-1))])])}const k=e(d,[["render",a]]);export{b as __pageData,k as default};
